#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LEN 64

static bool wildcard_match(const char *pattern, const char *text)
{
    size_t p_len = strlen(pattern);
    size_t t_len = strlen(text);
    bool dp[MAX_LEN + 1][MAX_LEN + 1] = {{false}};
    dp[0][0] = true;
    for (size_t i = 1; i <= p_len; ++i) {
        dp[i][0] = (pattern[i-1] == '*') ? dp[i-1][0] : false;
    }
    for (size_t i = 1; i <= p_len; ++i) {
        for (size_t j = 1; j <= t_len; ++j) {
            char pc = pattern[i-1];
            char tc = text[j-1];
            if (pc == '*') {
                dp[i][j] = dp[i-1][j] || dp[i][j-1];
            } else if (pc == '?' || pc == tc) {
                dp[i][j] = dp[i-1][j-1];
            } else {
                dp[i][j] = false;
            }
        }
    }
    return dp[p_len][t_len];
}

int main(int argc, char **argv)
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *pattern = argv[1];
    const char *text = argv[2];
    if (strlen(pattern) >= MAX_LEN || strlen(text) >= MAX_LEN) {
        puts("USAGE");
        return 0;
    }
    puts(wildcard_match(pattern, text) ? "MATCH" : "NO_MATCH");
    return 0;
}
